INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l27','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l27','live by selling','',NULL,'/lɪv baɪ ˈselɪŋ/','Everyone lives by selling something.','人人都靠卖点什么为生。','She lives by selling her paintings.','她靠卖画为生。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l27','free from care','',NULL,'/friː frəm ker/','He enjoys freedom from care.','他享受着无忧无虑。','For once I felt free from care.','我难得地感到无忧无虑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l27','with ease','',NULL,'/wɪð iːz/','He moves from place to place with ease.','他轻松地四处迁徙。','She passed the test with ease.','她轻松通过了考试。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l27','feel sorry for','',NULL,'/fiːl ˈsɑːri fɔːr/','He will never ask you to feel sorry for him.','他绝不会求你可怜他。','Don''t feel sorry for me.','别为我难过。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp1','choice','{"stem":"\"It is ___ that everyone lives by selling something.\"(被动“据说”)","options":["said","say","to say","saying"],"answer_index":0,"stem_cn":"据说人人都靠卖点什么为生。","explanation_cn":"“据说”用被动 It is said that…,said 是 say 的过去分词。✓ It is said that everyone… ✗ saying / say / to say:这里用过去分词 said。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp1','choice','{"stem":"\"The wanderer ___ said to enjoy total freedom.\"(“据说某人…”,用 be 的哪种形式)","options":["being","is","has","does"],"answer_index":1,"stem_cn":"据说那旅人享有彻底的自由。","explanation_cn":"“据说某人…”用 sb is said to do,这里用 is。✓ The wanderer is said to enjoy freedom. ✗ has / does / being:被动报道用 is said。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp1','choice','{"stem":"\"He is said ___ a very simple life.\"(sb is said + 不定式)","options":["lead","leading","led","to lead"],"answer_index":3,"stem_cn":"据说他过着极简单的生活。","explanation_cn":"sb is said + 不定式(to do)。✓ He is said to lead a simple life. ✗ leading / lead / led:said 后接 to do。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp2','choice','{"stem":"\"Teachers sell ___; it cannot be counted one by one.\"(不可数名词,不加 s)","options":["a knowledge","knowledges","knowledge","knowledge''s"],"answer_index":2,"stem_cn":"老师卖的是知识,不可数。","explanation_cn":"knowledge 是不可数名词,不加 s、前面不加 a。✓ sell knowledge. ✗ knowledges / a knowledge / knowledge''s:不可数,不变复数。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp2','choice','{"stem":"\"He gave me some useful ___ about traveling light.\"(不可数名词“建议”)","options":["advices","advice","an advice","advice''s"],"answer_index":1,"stem_cn":"关于轻装出行他给了我一些有用的建议。","explanation_cn":"advice 是不可数名词,不加 s、不用 an。✓ some useful advice. ✗ advices / an advice / advice''s:不可数,用 some advice。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp2','choice','{"stem":"\"The news ___ good, so everyone smiled.\"(news 不可数,用单数动词)","options":["have been","were","are","was"],"answer_index":3,"stem_cn":"消息不错,大家都笑了。","explanation_cn":"news 是不可数名词,作主语时动词用单数。✓ The news was good. ✗ were / are / have been:news 用单数动词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp3','choice','{"stem":"\"There ___ times when we would give everything to survive.\"(there be,一般现在,后接复数)","options":["is","are","has","have"],"answer_index":1,"stem_cn":"有时候我们愿付出一切求生。","explanation_cn":"there be + 复数(times)用 there are。✓ There are times when… ✗ is / has / have:后接复数名词用 are。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp3','choice','{"stem":"\"Long ago there ___ no stores to buy such things.\"(there be,一般过去,后接复数)","options":["has been","was","were","are"],"answer_index":2,"stem_cn":"很久以前没有商店能买到这类东西。","explanation_cn":"一般过去、后接复数(stores)用 there were。✓ there were no stores. ✗ was / are / has been:过去 + 复数用 were。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp3','choice','{"stem":"\"There ___ been a great change in his life.\"(there be,现在完成,后接单数)","options":["has","have","was","is"],"answer_index":0,"stem_cn":"他的生活发生了很大变化。","explanation_cn":"现在完成、后接单数(a great change)用 there has been。✓ There has been a great change. ✗ have / is / was:完成时单数用 has been。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp4','choice','{"stem":"\"He does a little work now and then ___ he can buy food.\"(目的“以便”,后接一个从句)","options":["in order","because","so that","so as"],"answer_index":2,"stem_cn":"他偶尔干点活,以便能买吃的。","explanation_cn":"目的“以便”,后面接一个带主语和动词的从句,用 so that。✓ so that he can buy food. ✗ so as / in order（后接 to do）/ because（表原因）。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp4','choice','{"stem":"\"He travels light ___ move from place to place easily.\"(目的“为了”,后接动词原形)","options":["because of","in order to","for to","so that"],"answer_index":1,"stem_cn":"他轻装出行,为的是方便四处走动。","explanation_cn":"目的“为了”,后面接动词原形,用 in order to。✓ in order to move easily. ✗ so that（接从句）/ for to / because of。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp4','choice','{"stem":"\"He walks quietly ___ wake the sleeping town.\"(目的否定“以免”)","options":["so as not to","not to so as","so as to not","for not to"],"answer_index":0,"stem_cn":"他轻手轻脚地走,以免吵醒沉睡的小镇。","explanation_cn":"目的的否定“以免”,后面接动词原形,用 so as not to。✓ so as not to wake the town. ✗ so as to not / for not to / not to so as:固定语序是 so as not to。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp5','choice','{"stem":"\"In our society, skills have ___ for like goods.\"(被动不定式“被支付”)","options":["paying","to be paid","to pay","paid"],"answer_index":1,"stem_cn":"在我们的社会里,技能也得像商品一样花钱买。","explanation_cn":"“技能被花钱买”用被动不定式 to be paid (for)。✓ skills have to be paid for. ✗ to pay / paying / paid:被动用 to be paid。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp5','choice','{"stem":"\"This is the kind of freedom ___ few people ever taste.\"(关系代词,指物)","options":["when","who","whose","which"],"answer_index":3,"stem_cn":"这是一种很少有人尝到的自由。","explanation_cn":"指物的关系代词用 which(或 that)。✓ the freedom which few people taste. ✗ who（指人）/ whose / when:指物用 which。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp5','choice','{"stem":"\"The friend with ___ he travels shares his simple life.\"(介词 + 关系代词,指人)","options":["which","whom","who","whose"],"answer_index":1,"stem_cn":"与他同行的朋友也过着这种简单生活。","explanation_cn":"“介词 + 关系代词”指人时用 whom。✓ the friend with whom he travels. ✗ which（指物）/ who（作宾语时介词后用 whom）/ whose:with 后用 whom。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp6','choice','{"stem":"\"A person who studies deep questions about life is a ___.\"(“哲学家”用哪个词)","options":["soldier","banker","farmer","philosopher"],"answer_index":3,"stem_cn":"研究人生深层问题的人。","explanation_cn":"研究人生深层问题的人是 philosopher(哲学家)。✓ a philosopher sells wisdom. ✗ farmer 农民;✗ soldier 士兵;✗ banker 银行家——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp6','choice','{"stem":"\"A strong feeling that someone is worthless is ___.\"(“蔑视”用哪个词)","options":["contempt","respect","joy","gratitude"],"answer_index":0,"stem_cn":"认为某人一文不值的强烈感觉。","explanation_cn":"认为某人一文不值的强烈感觉是 contempt(蔑视)。✓ speak with contempt. ✗ respect 尊敬;✗ gratitude 感激;✗ joy 喜悦——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',5,'am3_l27_gp6','choice','{"stem":"\"Wanting what someone else has is being ___.\"(“嫉妒的”用哪个词)","options":["honest","envious","calm","generous"],"answer_index":1,"stem_cn":"想要别人拥有的东西。","explanation_cn":"想要别人拥有的东西就是 envious(嫉妒的)。✓ felt a little envious. ✗ generous 慷慨;✗ honest 诚实;✗ calm 平静——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"philosopher 的意思是:","options":["士兵","银行家","农民","哲学家"],"answer_index":3,"explanation_cn":"philosopher = 哲学家。✓ a philosopher sells wisdom 哲学家卖智慧。\n顺带记:农民 = farmer;士兵 = soldier;银行家 = banker."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"priest 的意思是:","options":["演员","牧师","教师","医生"],"answer_index":1,"explanation_cn":"priest = 牧师。✓ priests sell comfort 牧师卖慰藉。\n顺带记:医生 = doctor;教师 = teacher;演员 = actor."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"dignity 的意思是:","options":["财富","恐惧","尊严","懒惰"],"answer_index":2,"explanation_cn":"dignity = 尊严。✓ he does not give up his dignity 他不丢尊严。\n顺带记:财富 = wealth;恐惧 = fear;懒惰 = laziness."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"deliberately 的意思是:","options":["故意地","缓慢地","安静地","偶然地"],"answer_index":0,"explanation_cn":"deliberately = 故意地、有意地。✓ he has deliberately chosen 他有意选择。\n顺带记:偶然地 = accidentally;缓慢地 = slowly;安静地 = quietly."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"contempt 的意思是:","options":["感激","喜爱","敬佩","蔑视"],"answer_index":3,"explanation_cn":"contempt = 蔑视。✓ speak with contempt 带着蔑视谈论。\n顺带记:敬佩 = admiration;感激 = gratitude;喜爱 = affection."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',6,NULL,'choice','{"stem":"envious 的意思是:","options":["嫉妒的,羡慕的","诚实的","慷慨的","勇敢的"],"answer_index":0,"explanation_cn":"envious = 嫉妒的、羡慕的。✓ felt a little envious 有点羡慕。\n顺带记:慷慨的 = generous;勇敢的 = brave;诚实的 = honest."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',7,NULL,'cloze','{"stem":"第 1 空","context":"It ___1___ said that everyone lives by selling something. Even ___2___, which cannot be counted, is sold by teachers as knowledge. There ___3___ times, though, when a person wants nothing to sell. The free wanderer travels light ___4___ he can move with ease.","blank_no":1,"options":["is","has","are","being"],"answer_index":0,"explanation_cn":"“据说”用被动 It is said that…。✓ It is said that everyone lives by selling something."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',7,NULL,'cloze','{"stem":"第 2 空","context":"It ___1___ said that everyone lives by selling something. Even ___2___, which cannot be counted, is sold by teachers as knowledge. There ___3___ times, though, when a person wants nothing to sell. The free wanderer travels light ___4___ he can move with ease.","blank_no":2,"options":["information","informations","an information","information''s"],"answer_index":0,"explanation_cn":"information 是不可数名词,不加 s、不用 an。✓ Even information is sold as knowledge."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',7,NULL,'cloze','{"stem":"第 3 空","context":"It ___1___ said that everyone lives by selling something. Even ___2___, which cannot be counted, is sold by teachers as knowledge. There ___3___ times, though, when a person wants nothing to sell. The free wanderer travels light ___4___ he can move with ease.","blank_no":3,"options":["are","is","was","has"],"answer_index":0,"explanation_cn":"there be + 复数(times)用 there are。✓ There are times when…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',7,NULL,'cloze','{"stem":"第 4 空","context":"It ___1___ said that everyone lives by selling something. Even ___2___, which cannot be counted, is sold by teachers as knowledge. There ___3___ times, though, when a person wants nothing to sell. The free wanderer travels light ___4___ he can move with ease.","blank_no":4,"options":["so that","so as","for to","because"],"answer_index":0,"explanation_cn":"目的“以便”,后接一个从句,用 so that。✓ so that he can move with ease."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',8,NULL,'choice','{"stem":"According to the writer, how does society treat skills?","options":["They are always given for free","They belong to no one","They cannot be valued at all","They must be paid for, like goods"],"answer_index":3,"explanation_cn":"课文说 skills have to be paid for in the same way that goods have to be paid for——技能像商品一样要花钱买。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',8,NULL,'choice','{"stem":"How is the free wanderer different from a beggar?","options":["He is much richer","He asks for nothing and keeps his dignity","He works every single day","He owns a large home"],"answer_index":1,"explanation_cn":"课文说 the true wanderer has nothing to sell and asks nothing…does not give up his dignity——他无所求且不失尊严,与乞丐不同。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',8,NULL,'choice','{"stem":"What does the wanderer value most?","options":["His freedom","His reputation","His money","His possessions"],"answer_index":0,"explanation_cn":"课文说 he will never trade away his freedom——他最看重的是自由。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',9,NULL,'choice','{"stem":"你想说\"据说人人都靠卖点什么为生\"(It is said that):","options":["It is say that everyone lives by selling something.","It is said everyone lives by selling something that.","It is said that everyone lives by selling something.","It says that everyone lives by selling something."],"answer_index":2,"explanation_cn":"“据说”用被动 It is said that…。✓ It is said that everyone lives by selling something. 场合:转述普遍看法而不点明是谁说的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',9,NULL,'choice','{"stem":"你想说\"有时候我们愿付出一切\"(There are times when):","options":["There are times when we would give everything.","There have times when we would give everything.","It are times when we would give everything.","There is times when we would give everything."],"answer_index":0,"explanation_cn":"there be + 复数(times)用 there are。✓ There are times when we would give everything. 场合:说“有时候…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',9,NULL,'choice','{"stem":"你想说\"他轻装出行,以便四处走动\"(so that):","options":["He travels light so that to move easily.","He travels light for that he can move easily.","He travels light so as he can move easily.","He travels light so that he can move easily."],"answer_index":3,"explanation_cn":"目的“以便”用 so that + 一个完整的从句(有它自己的动词)。✓ He travels light so that he can move easily. 场合:说做某事的目的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"philosopher 的意思是:","options":["士兵","银行家","哲学家","农民"],"answer_index":2,"explanation_cn":"philosopher = 哲学家。✓ a philosopher sells wisdom."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"envious 的意思是:","options":["慷慨的","诚实的","勇敢的","嫉妒的,羡慕的"],"answer_index":3,"explanation_cn":"envious = 嫉妒的、羡慕的。✓ felt a little envious."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"\"It is ___ that everyone lives by selling something.\"(被动“据说”)","options":["to say","said","say","saying"],"answer_index":1,"stem_cn":"据说人人都靠卖点什么为生。","explanation_cn":"“据说”用被动 It is said that…,用过去分词 said。✓ It is said that everyone lives by selling something. ✗ saying / say / to say:用过去分词 said。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"\"There ___ times when we would give everything.\"(there be,后接复数)","options":["was","has","are","is"],"answer_index":2,"stem_cn":"有时候我们愿付出一切。","explanation_cn":"there be + 复数(times)用 there are。✓ There are times when we would give everything. ✗ is / was / has:后接复数用 are。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"\"free from care\" 的意思是:","options":["免费护理","不小心","不在乎钱","无忧无虑"],"answer_index":3,"explanation_cn":"free from care = 无忧无虑。✓ their freedom from care 他们无忧无虑的生活。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"\"with ease\" 的意思是:","options":["慢慢地","轻松地,不费力","面带愁容","带着东方风情"],"answer_index":1,"explanation_cn":"with ease = 轻松地、不费力。✓ move with ease 轻松地迁徙。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"Why is it hard to value the services people perform?","options":["They are all illegal","No one ever performs them","Their true worth cannot be measured in money","They are always free"],"answer_index":2,"passage":"It has been said that everyone lives by selling something. Seen in this light, teachers live by selling knowledge, doctors by selling health, and priests by selling comfort. Though the value of material goods can be measured in money, it is extremely difficult to estimate the true worth of the services people perform for us. There are times when we would gladly give everything we own to save our lives, and yet we might resent paying a surgeon a large fee for offering us exactly that service. Society is arranged so that skills have to be paid for in the same way that goods have to be paid for in a store. Everyone, it seems, has something to sell. The free-spirited wanderer seems to be the one exception to this rule. Unlike a beggar, who in a sense sells his own misfortune for the pity of passers-by, the true wanderer has nothing to sell and asks nothing of others. In seeking his independence, he does not give up his dignity. He may ask you for a few dollars, but he will never ask you to feel sorry for him. He has deliberately chosen the life he leads and is fully aware of its consequences. He can never be sure where his next meal is coming from, yet he is free from the thousands of anxieties that afflict the rest of us. With few possessions, he can move from place to place with ease, and by sleeping under the open sky he comes far closer to nature than most of us ever do. Now and then, in times of real need, he will do a little work, but he will never trade away his freedom. We often speak of such people with contempt, yet how many of us have never felt just a little envious of their simple life and their freedom from care?","explanation_cn":"课文说 it is extremely difficult to estimate the true worth of the services——服务的真正价值很难用钱衡量。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"Why might we secretly envy the free wanderer?","options":["For his simple life and freedom from care","For his big house","For his great wealth","For his worldwide fame"],"answer_index":0,"passage":"It has been said that everyone lives by selling something. Seen in this light, teachers live by selling knowledge, doctors by selling health, and priests by selling comfort. Though the value of material goods can be measured in money, it is extremely difficult to estimate the true worth of the services people perform for us. There are times when we would gladly give everything we own to save our lives, and yet we might resent paying a surgeon a large fee for offering us exactly that service. Society is arranged so that skills have to be paid for in the same way that goods have to be paid for in a store. Everyone, it seems, has something to sell. The free-spirited wanderer seems to be the one exception to this rule. Unlike a beggar, who in a sense sells his own misfortune for the pity of passers-by, the true wanderer has nothing to sell and asks nothing of others. In seeking his independence, he does not give up his dignity. He may ask you for a few dollars, but he will never ask you to feel sorry for him. He has deliberately chosen the life he leads and is fully aware of its consequences. He can never be sure where his next meal is coming from, yet he is free from the thousands of anxieties that afflict the rest of us. With few possessions, he can move from place to place with ease, and by sleeping under the open sky he comes far closer to nature than most of us ever do. Now and then, in times of real need, he will do a little work, but he will never trade away his freedom. We often speak of such people with contempt, yet how many of us have never felt just a little envious of their simple life and their freedom from care?","explanation_cn":"课文说 envious of their simple life and their freedom from care——我们暗地里羡慕他们简单而无忧的生活。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"Whom does the writer compare a beggar with?","options":["A philosopher","The free wanderer","A surgeon","A teacher"],"answer_index":1,"audio":"It has been said that everyone lives by selling something. Seen in this light, teachers live by selling knowledge, doctors by selling health, and priests by selling comfort. Though the value of material goods can be measured in money, it is extremely difficult to estimate the true worth of the services people perform for us. There are times when we would gladly give everything we own to save our lives, and yet we might resent paying a surgeon a large fee for offering us exactly that service. Society is arranged so that skills have to be paid for in the same way that goods have to be paid for in a store. Everyone, it seems, has something to sell. The free-spirited wanderer seems to be the one exception to this rule. Unlike a beggar, who in a sense sells his own misfortune for the pity of passers-by, the true wanderer has nothing to sell and asks nothing of others. In seeking his independence, he does not give up his dignity. He may ask you for a few dollars, but he will never ask you to feel sorry for him. He has deliberately chosen the life he leads and is fully aware of its consequences. He can never be sure where his next meal is coming from, yet he is free from the thousands of anxieties that afflict the rest of us. With few possessions, he can move from place to place with ease, and by sleeping under the open sky he comes far closer to nature than most of us ever do. Now and then, in times of real need, he will do a little work, but he will never trade away his freedom. We often speak of such people with contempt, yet how many of us have never felt just a little envious of their simple life and their freedom from care?","explanation_cn":"课文把 beggar 和 the true wanderer 作对比——乞丐卖不幸,旅人无所求。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l27',10,NULL,'choice','{"stem":"Where does the wanderer often sleep?","options":["In fancy hotels","On a train","Under the open sky","In a big house"],"answer_index":2,"audio":"It has been said that everyone lives by selling something. Seen in this light, teachers live by selling knowledge, doctors by selling health, and priests by selling comfort. Though the value of material goods can be measured in money, it is extremely difficult to estimate the true worth of the services people perform for us. There are times when we would gladly give everything we own to save our lives, and yet we might resent paying a surgeon a large fee for offering us exactly that service. Society is arranged so that skills have to be paid for in the same way that goods have to be paid for in a store. Everyone, it seems, has something to sell. The free-spirited wanderer seems to be the one exception to this rule. Unlike a beggar, who in a sense sells his own misfortune for the pity of passers-by, the true wanderer has nothing to sell and asks nothing of others. In seeking his independence, he does not give up his dignity. He may ask you for a few dollars, but he will never ask you to feel sorry for him. He has deliberately chosen the life he leads and is fully aware of its consequences. He can never be sure where his next meal is coming from, yet he is free from the thousands of anxieties that afflict the rest of us. With few possessions, he can move from place to place with ease, and by sleeping under the open sky he comes far closer to nature than most of us ever do. Now and then, in times of real need, he will do a little work, but he will never trade away his freedom. We often speak of such people with contempt, yet how many of us have never felt just a little envious of their simple life and their freedom from care?","explanation_cn":"课文说 by sleeping under the open sky——旅人常睡在露天。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
